int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;

    if (!c->nb_streams) {
        return AVERROR_INVALIDDATA;
    }

    entries = avio_rb32(pb); // Read number of entries
    if (entries <= 0) {
        return 0;
    }

    for (i = 0; i < entries; i++) {
        uint32_t type;
        uint16_t version, flags;
        int size;

        type = avio_rl32(pb);
        version = avio_rb16(pb);
        flags = avio_rb16(pb);

        size = avio_rb32(pb); // Read size of entry

        if (type == MKTAG('a','l','i','a')) { // Macintosh alias record
            int offset = 0;
            int alias_size = size;
            int parent_folder_count = 0;
            int name_length = 0;
            char *filename = NULL;

            // Skip reserved fields
            avio_skip(pb, 4);

            // Read parent folder count
            parent_folder_count = avio_rl16(pb);
            avio_skip(pb, parent_folder_count * 2);

            // Read name length
            name_length = avio_rl16(pb);
            if (name_length > 0) {
                filename = av_mallocz(name_length + 1);
                if (!filename) {
                    return AVERROR(ENOMEM);
                }
                avio_read(pb, filename, name_length);
                filename[name_length] = '\0';
            }

            // Skip remaining data
            avio_skip(pb, alias_size - (offset + 12 + parent_folder_count * 2 + name_length));

            if (filename) {
                av_freep(&filename);
            }
        } else if (type == MKTAG('u','r','l',' ')) {
            int is_self_contained = !!(flags & 0x01);
            int len = size - 12;
            char *url = av_mallocz(len + 1);
            if (!url) {
                return AVERROR(ENOMEM);
            }
            avio_read(pb, url, len);
            url[len] = '\0';
            av_freep(&url);
        } else {
            avio_skip(pb, size - 4); // Skip unknown type
        }
    }

    return 0;
}

