int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i;
    int entries;

    if (!c->nb_streams) {
        return AVERROR_INVALIDDATA;
    }

    entries = avio_rb32(pb); // Read number of entries

    for (i = 0; i < entries; i++) {
        char type[5];
        int size;

        size = avio_rb32(pb); // Read entry size
        avio_read(pb, type, 4);
        type[4] = 0;

        // Handle each entry type (e.g., 'alii', 'alis', 'url ')
        if (!strcmp(type, "alii") || !strcmp(type, "alis")) {
            // Macintosh alias record handling
            int flags = avio_rb16(pb);
            avio_skip(pb, 2); // reserved

            if (flags & 1) {
                // Read alias data
                avio_skip(pb, 22); // alias data length
            }
        } else if (!strcmp(type, "url ")) {
            // URL handler
            int flags = avio_rb16(pb);
            avio_skip(pb, 2); // reserved

            if (!(flags & 1)) {
                // Read the filename
                char *filename = av_malloc(size - 8);
                if (!filename) {
                    return AVERROR(ENOMEM);
                }
                avio_read(pb, filename, size - 8);
                // Store filename or handle as needed
                av_free(filename);
            } else {
                avio_skip(pb, size - 8);
            }
        } else {
            // Skip unknown entry types
            avio_skip(pb, size - 4);
        }
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i, entries;
    int64_t size;

    if (!c->nb_streams) {
        avio_skip(pb, atom.size);
        return 0;
    }

    entries = avio_rb32(pb);
    if (entries < 0)
        return AVERROR_INVALIDDATA;

    for (i = 0; i < entries; i++) {
        int len = avio_rb32(pb);
        uint32_t type = avio_rl32(pb);

        avio_skip(pb, 4); // Skip data size
        if (type == MKTAG('a','l','i','a')) {
            // Handle Macintosh alias record
            int64_t pos = avio_tell(pb);
            avio_skip(pb, 4); // Skip nested data size
            avio_skip(pb, 4); // Skip alias data
            avio_seek(pb, pos + len, SEEK_SET);
        } else if (type == MKTAG('u','r','l',' ')) {
            int flags = avio_rb32(pb);
            if (!(flags & 1))
                avio_skip(pb, len - 8);
        } else {
            avio_skip(pb, len - 8);
        }
    }

    return 0;
}

int mov_read_dref(MOVContext *c, AVIOContext *pb, MOVAtom atom) {
    int i, entries;
    MOVTrack *track;

    if (!c->nb_streams) {
        avio_skip(pb, atom.size);
        return 0;
    }

    track = c->streams[c->cur_stream];
    if (!track) {
        avio_skip(pb, atom.size);
        return AVERROR_INVALIDDATA;
    }

    entries = avio_rb32(pb); // number of entries
    if (entries < 0 || (uint64_t)entries > atom.size) {
        avio_skip(pb, atom.size);
        return AVERROR_INVALIDDATA;
    }

    for (i = 0; i < entries; i++) {
        uint32_t size = avio_rb32(pb);
        uint32_t type = avio_rl32(pb);

        if (size < 4) {
            avio_skip(pb, atom.size);
            return AVERROR_INVALIDDATA;
        }

        size -= 4; // account for size field

        if (type == MKTAG('a','l','i','a')) {
            // Macintosh alias record
            int flags = avio_rb16(pb);
            int32_t data_size = avio_rb32(pb);
            if (data_size > 0) {
                avio_skip(pb, data_size);
                size -= data_size;
            }
        } else {
            // Other types
            avio_skip(pb, size);
        }
    }

    return 0;
}
